using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Web.Script.Serialization;
namespace PZ3D {
 static class GameLogAnalyzerTests {
  static int passed;
  static void Check(bool value,string name){if(!value)throw new Exception("FAIL: "+name);passed++;Console.WriteLine("PASS: "+name);}
  static GameLogReport Analyze(params GameLogInput[] inputs){var t=typeof(GameLogReport).Assembly.GetType("PZ3D.GameLogAnalyzer");Check(t!=null,"generic analyzer exists");try{return (GameLogReport)t.GetMethod("Analyze",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{inputs,CancellationToken.None,null});}catch(TargetInvocationException e){throw e.InnerException;}}
  static GameLogInput Input(string text,string session){return new GameLogInput{Id="source-"+session,Name="console.txt",Kind="imported",SessionKey=session,Encoding="utf-8",Length=text.Length,Open=()=>new StringReader(text)};}
  static GameLogReport Text(string text){return Analyze(Input(text,"one"));}
  // Catches assuming a known MOD name, losing B42 script locations, or calling runtime errors join failures.
  static void ArbitraryLua(){var r=Text("ERROR: General > dumping Lua stack trace\nLua((MOD:Unseen Workshop Name)).tick(media/lua/client/fiction.lua:248)\nERROR: General > Exception thrown\njava.lang.RuntimeException: attempted index: health of non-table: null\nLua((MOD:Unseen Workshop Name)).tick(media/lua/client/fiction.lua:248)\nzombie.gameStates.IngameState.update(IngameState.java:1370)\n");var i=r.issues.Single(x=>x.type=="lua-null-index");Check(i.mods.Contains("Unseen Workshop Name"),"arbitrary MOD metadata identified");Check(i.frames.Any(f=>f.file=="media/lua/client/fiction.lua"&&f.line==248),"relative script path and line retained");Check(i.meaning.Contains("health")&&i.meaning.Contains("空"),"null field explained in Chinese");Check(r.state=="entered-with-issues"&&i.phase=="runtime"&&i.impact=="runtime","runtime stack is gameplay evidence, not join failure");Check(i.evidence.Any(e=>e.line==4&&e.text.Contains("attempted index")),"original exception source line retained");}
  // Catches grouping all headers together or counting Lua display copies as independent exceptions.
  static void Grouping(){string block="ERROR: General > dumping Lua stack trace\nLua((MOD:Never Seen)).run(a.lua:12)\nERROR: General > Exception thrown\njava.lang.RuntimeException: Object tried to call nil in run\nLua((MOD:Never Seen)).run(a.lua:12)\n";var r=Text(block+block+"ERROR: General > Exception thrown\njava.lang.RuntimeException: __len not defined for operand\nLua((MOD:Never Seen)).run(b.lua:25)\n");Check(r.issues.Length==2,"distinct exceptions group by message and frames");Check(r.issues.Single(x=>x.type=="lua-call-nil").count==2,"repeated exception count ignores generic and dump headers");Check(r.issues.Single(x=>x.type=="lua-length").frames.Any(f=>f.file=="b.lua"),"separate stack retained");}
  // Catches discarding B41 metadata preceding the Java exception.
  static void OldLua(){var r=Text("ERROR: General > dumping Lua stack trace\nfunction: callback -- file: media/lua/client/Old.lua line # 84 | MOD: Fictional Legacy Pack\njava.lang.RuntimeException: Object tried to call nil\n");Check(r.issues.Any(x=>x.mods.Contains("Fictional Legacy Pack")&&x.frames.Any(f=>f.line==84&&f.function=="callback")),"legacy Lua frames before exception retained");}
  // Catches throwing unknown messages away before their stack arrives or retaining stacks across ordinary records.
  static void UnknownFrames(){foreach(string severity in new[]{"ERROR","WARN"})foreach(bool before in new[]{false,true}){string frame="Lua((MOD:Arbitrary Pack)).tick(a.lua:42)\n",error=severity+": unfamiliar callback failed\n";var r=Text(before?frame+error:error+frame);Check(r.issues.Any(i=>i.type=="unclassified"&&i.mods.Contains("Arbitrary Pack")&&i.frames.Any(f=>f.file=="a.lua"&&f.line==42)),"unknown "+severity+" retains "+(before?"preceding":"following")+" MOD frames");}var separate=Text("ERROR: unfamiliar callback failed\nLOG: ordinary loading progress\nLua((MOD:Unrelated Pack)).tick(other.lua:90)\n");Check(separate.issues.Single().mods.Length==0,"ordinary record closes unknown error before unrelated frame");}
  // Catches treating explanatory text as actual exception or state-event syntax.
  static void ObservationalGrammar(){foreach(string text in new[]{"WARN: optional error example: Cannot load world","ERROR: documentation: Cannot load world","LOG: loaded error handler for java.lang.OutOfMemoryError: Java heap space","INFO: docs mention zombie.gameStates.IngameState.update(IngameState.java:1)","WARN: optional connection-attempt-failed example","LOG: example STATE: exit zombie.gameStates.GameLoadingState"}){var r=Text(text);Check(r.state=="unknown"&&r.issues.All(i=>i.impact!="blocking"&&i.type!="java-heap"),"mention is not actual failure or gameplay: "+text);}Check(Text("zombie.world.WorldDictionaryException: Cannot load world due to WorldDictionary error").state=="failed","unprefixed actual world exception stays blocking");}
  // Catches rejecting actual exception classes/messages solely because their payload contains an ordinary word.
  static void ExceptionPayloadWords(){var r=Text("com.example.MyException: operation failed\n at com.example.Handler.run(Handler.java:14)\n");Check(r.issues.Any(i=>i.type=="java-exception"&&i.frames.Any(f=>f.function=="com.example.Handler.run"&&f.line==14)),"actual exception class may contain example package");r=Text("java.lang.OutOfMemoryError: Java heap space while decoding sample\n");Check(r.issues.Any(i=>i.type=="java-heap"),"actual exception message may contain sample");r=Text("ERROR: required mod \"Documentation Sample\" not found\n");Check(r.issues.Any(i=>i.type=="missing-dependency"),"dependency names may contain documentation and sample");}
  // Catches exports dropping source-name/session mappings needed to locate a multi-input observation.
  static void ExportProvenance(){var input=Input("ERROR: unfamiliar callback failed\n","session-fiction");input.Id="source-fiction";input.Name="fiction_DebugLog.txt";var r=Analyze(input);Check(r.reportText.Contains("source-fiction")&&r.reportText.Contains("fiction_DebugLog.txt")&&r.reportText.Contains("utf-8")&&r.reportText.Contains("session-fiction")&&r.reportText.Contains(r.issues.Single().attemptId),"export retains source names encoding session and issue attempt");}
  // Catches promoting network acceptance/loading duration/mod timeout to completed gameplay.
  static void ConservativeOutcomes(){foreach(string s in new[]{"connection-request-accepted","receivePlayerConnect","send-packet / player-connect","game loading took 34 seconds","MOD reason=client_timeout controlsRestored=true","Disconnecting"})Check(Text(s).state=="unknown","weak event remains unknown: "+s);var r=Text("connection-attempt-failed\nconnection-request-accepted\nSTATE: exit zombie.gameStates.GameLoadingState\n");Check(r.state=="entered"&&r.attempts.Length>=2&&r.attempts[0].state=="failed","later retry success supersedes earlier failure");r=Text("zombie.gameStates.IngameState.update(IngameState.java:1)\nERROR: Cannot load world due to WorldDictionary error\n");Check(r.state=="failed"&&r.issues.Any(i=>i.type=="world-load"&&i.impact=="blocking"),"later explicit world failure supersedes earlier gameplay");r=Analyze(Input("STATE: exit zombie.gameStates.GameLoadingState\n","old"),Input("ERROR: mystery observation\n","new"));Check(r.state=="unknown"&&r.issues.All(i=>i.phase!="runtime"),"unrelated sessions do not lend success or runtime context");}
  // Catches two-digit-year DebugLog prefixes losing severity and companion file iteration undoing gameplay.
  static void CompanionTimeline(){var debug=Input("[22-10-26 01:12:20.000] LOG : General > STATE: exit zombie.gameStates.GameLoadingState\n[22-10-26 01:12:21.000] WARN : General > Message: ERROR: formatting\n","paired");debug.Id="debug";var conn=Input("[22-10-26 01:11:25.096] event=\"RakNet\" message=\"connection-attempt-failed\"\n[22-10-26 01:11:57.148] event=\"RakNet\" message=\"connection-request-accepted\"\n","paired");conn.Id="connections";var r=Analyze(debug,conn);Check(r.state=="entered"&&r.warningCount==1&&r.errorCount==0,"dated companion connection retry merges chronologically");debug=Input("STATE: exit zombie.gameStates.GameLoadingState\n","paired");debug.Id="debug";conn=Input("connection-attempt-failed\nconnection-request-accepted\n","paired");conn.Id="connections";Check(Analyze(debug,conn).state=="entered","undated companion old network events cannot undo world progress");}
  // Catches early warning floods hiding terminal evidence and treating a message's 'Exception thrown' as a display header.
  static void TerminalRetention(){string flood=string.Join("\n",Enumerable.Range(1,100).Select(x=>"WARN: unfamiliar warning "+x))+"\n";var r=Text(flood+"ERROR: Cannot load world due to WorldDictionary error\n");Check(r.issues.Any(i=>i.type=="world-load")&&r.state=="failed","late world failure retained beyond group limit");r=Text(flood+"ERROR: General > Unhandled java.lang.NullPointerException thrown by thread MainThread.\nERROR: General > GameWindow.uncaughtException> Exception thrown\njava.lang.NullPointerException: Required Animation Asset not found: fictional/idle at ModelManager.getAnimationAssetRequired(ModelManager.java:1890). Message: Unhandled java.lang.NullPointerException thrown by thread MainThread.\njava.base/java.lang.Thread.run(Unknown Source)\nLOG : General > GameThread exited.\n");Check(r.state=="failed"&&r.issues.Any(i=>i.type=="missing-resource"&&i.impact=="blocking"&&i.evidence.Any(e=>e.text.Contains("fictional/idle"))),"late multiline required resource and thread exit remain blocking");Check(r.issues.Single(i=>i.type=="missing-resource").evidence.Any(e=>e.text.Contains("GameThread exited")),"blocking classification retains terminal event evidence");r=Analyze(Input("connection-attempt-failed\n","a"),Input("STATE: exit zombie.gameStates.GameLoadingState\n","b"));Check(r.state=="unknown"&&r.summary.Contains("会话"),"unrelated sessions do not become arbitrary last result");}
  // Catches hiding unfamiliar error/warning text or conflating missing animation with download failure.
  static void GenericErrors(){var r=Text("ERROR: a fictional subsystem reports wobble\nWARN: optional widget unavailable\nWARN : General > Message: ERROR: formatting\njava.lang.NullPointerException: Required Animation Asset not found: fictional/idle\nGameThread exited\n");Check(r.issues.Any(i=>i.type=="unclassified"&&i.severity=="error")&&r.issues.Any(i=>i.severity=="warning"),"unknown ERROR and WARN observations kept");Check(r.errorCount==1&&r.warningCount==2,"severity counters use line prefix, not embedded ERROR");var asset=r.issues.Single(i=>i.type=="missing-resource");Check(asset.meaning.Contains("资源")&&asset.advice.Contains("验证")&&!asset.meaning.Contains("下载失败"),"missing resource advice states evidence without guessed cause");Check(r.state=="failed","required missing asset followed by thread exit is blocking");foreach(string pair in new[]{"java.lang.OutOfMemoryError: Java heap space|java-heap","# Native memory allocation (malloc) failed to allocate 10 bytes|native-memory","ERROR: required mod \"Fictional Parent\" not found|missing-dependency","ERROR: checksum mismatch|checksum","ERROR: Workshop download failed|workshop"}){var p=pair.Split('|');Check(Text(p[0]).issues.Any(i=>i.type==p[1]),"generic failure rule "+p[1]);}}
  // Catches leaks through names, session keys, mod names, frames or derived report text.
  static void Privacy(){string text="ERROR: password=secret-pwd\nERROR: token=secret-ticket\nERROR: username=secret-account\nERROR: Authorization: Bearer secret-bearer\nERROR: 192.168.22.33 2001:db8::1234 76561198012345678 STEAM_0:1:123456 [U:1:123456]\njava.lang.RuntimeException: Object tried to call nil C:\\Users\\secret-user\\file.txt /home/secret-unix/private\nLua((MOD:username=secret-mod)).callback(C:\\Users\\secret-frame\\private.lua:13)\n";var input=Input(text,"password=secret-session");input.Name="C:\\Users\\secret-name\\console.txt";string json=new JavaScriptSerializer().Serialize(Analyze(input));foreach(string secret in new[]{"secret-pwd","secret-ticket","secret-account","secret-bearer","192.168.22.33","2001:db8::1234","76561198012345678","STEAM_0:1:123456","[U:1:123456]","secret-user","secret-unix","secret-frame","secret-mod","secret-session","secret-name"})Check(!json.Contains(secret),"all report fields redact "+secret);}
  // Catches unbounded input lines/issues/evidence and swallowed cancellation.
  static void Bounds(){var r=Text(new string('x',200000)+"\njava.lang.OutOfMemoryError: Java heap space\n"+string.Join("\n",Enumerable.Range(1,300).Select(x=>"ERROR: distinct "+x)));Check(r.incomplete&&r.issues.Length<=80&&r.issues.Any(i=>i.type=="java-heap"),"long line skipped safely and issue output bounded");Check(r.issues.All(i=>i.evidence.Length<=12&&i.evidence.All(e=>e.text.Length<=800)),"evidence bounded");var token=new CancellationToken(true);bool cancelled=false;var t=typeof(GameLogReport).Assembly.GetType("PZ3D.GameLogAnalyzer");try{t.GetMethod("Analyze",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{new[]{Input("x","one")},token,null});}catch(TargetInvocationException e){cancelled=e.InnerException is OperationCanceledException;}Check(cancelled,"cancellation is honored");Check(Text("").state=="unknown","empty input cannot claim success");}
  public static int Main(){int failures=0;foreach(var run in new Action[]{ArbitraryLua,Grouping,OldLua,UnknownFrames,ObservationalGrammar,ExceptionPayloadWords,ExportProvenance,ConservativeOutcomes,CompanionTimeline,TerminalRetention,GenericErrors,Privacy,Bounds})try{run();}catch(Exception e){failures++;Console.WriteLine(e);}Console.WriteLine("Log analyzer assertions passed="+passed+", groups failed="+failures);return failures==0?0:1;}
 }
}
